return {title,objective,theory,practice,metric,checkQuestion:question,quiz:{question,options,correctIndex:correct},duration:5,
steps:['За 1 минуту пойми цель и ключевую идею.','За 2 минуты разберись в примере и объясни принцип своими словами.','За 1 минуту ответь на проверочный вопрос без подсказки.','За 1 минуту примени принцип к своей ситуации и запиши результат.'],
sources:[{title:source[0],url:source[1]}]};
